Because the field is declared `final`, Java requires it to be assigned at construction time. You currently have a final field with `@Autowired` field injection but no constructor or Lombok annotation to initialize it, so the compiler complains. Use constructor injection (recommended). You can either add a constructor or use Lombok's `@RequiredArgsConstructor`.

Updated file `backend/src/main/java/dev/jclawlor/FitnessGoals/controller/ExerciseController.java` using Lombok constructor injection:

```java
package dev.jclawlor.FitnessGoals.controller;

import java.util.List;

import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

import dev.jclawlor.FitnessGoals.dto.CardioExerciseDto;
import dev.jclawlor.FitnessGoals.dto.LiftingExerciseDto;
import dev.jclawlor.FitnessGoals.entity.CardioExercise;
import dev.jclawlor.FitnessGoals.entity.Exercise;
import dev.jclawlor.FitnessGoals.entity.LiftingExercise;
import dev.jclawlor.FitnessGoals.service.impl.ExerciseServiceImpl;
import jakarta.validation.Valid;
import lombok.RequiredArgsConstructor;

@RestController
@RequestMapping("/api/exercises")
@RequiredArgsConstructor
public class ExerciseController {

    private final ExerciseServiceImpl exerciseService;

    @GetMapping
    public ResponseEntity<List<Exercise>> getAllExercises() {
        return ResponseEntity.ok(exerciseService.getAllExercises());
    }

    @PostMapping("/lifting")
    public ResponseEntity<LiftingExercise> addLifting(@Valid @RequestBody LiftingExerciseDto dto) {
        return ResponseEntity.status(HttpStatus.CREATED).body(exerciseService.addLiftingExercise(dto));
    }

    @PostMapping("/cardio")
    public ResponseEntity<CardioExercise> addCardio(@Valid @RequestBody CardioExerciseDto dto) {
        return ResponseEntity.status(HttpStatus.CREATED).body(exerciseService.addCardioExercise(dto));
    }
}
```
